clc; clearvars;
%%
%[text] Load real data
root_dir = "..";
addpath(genpath(fullfile(root_dir, "\O3_Lidar\proc_functions")))
dataPath = fullfile(root_dir, "lidar_data\20251027");

data_format     = "bin"; %[control:dropdown:2488]{"position":[19,24]}
prefix = "ol";

SNR_lim = 10;
n_shots = 1200;
tau = 1/(40e6);
dz = 3.75;
n_avg = 1;
fd = 270;

[an_R,pc_R,times,configs] = read_lidar_datafiles(dataPath,data_format,prefix);

n_bins = size(an_R,1);
n_prof = size(an_R,2);

h = (dz.*(1:n_bins))';
hkm = h./1000;

n_prof_avg = floor(n_prof / n_avg);

[an_bin,pc_P,times,an_B,pc_B] = preprocess(an_R,pc_R,times,dz,n_avg,n_shots,fd);
an_bin_bg = an_bin - an_B;
pc_P_bg = pc_P - pc_B;

an_bin_bg(an_bin_bg <= 0) = NaN;
pc_P_bg(pc_P_bg <= 0) = NaN;

an_mV_avg = scale_binary_analog(an_bin_bg,0,16,1201);
pc_p_avg = scale_binary_pc(pc_P_bg,3.75,1201);

etaQ_287 = 0.3;
etaQ_299 = 0.3;

mu_287 = 3e5;
mu_299 = 3e5;

id = 1; %[control:slider:32ba]{"position":[6,7]}

an_287 = an_mV_avg(:,id,1);
an_299 = an_mV_avg(:,id,2);

pc_287 = pc_p_avg(:,id,1);
pc_299 = pc_p_avg(:,id,2);
%%
load("C.mat")
C_287 = (interp1(C_grid,C_nsy_287(:,1),h) - CB_287) .* 1e-6;
C_299 = (interp1(C_grid,C_nsy_299(:,1),h) - CB_299) .* 1e-6;
%%
x_lim = [0 20];

figure; %[output:7c3dffe5]
semilogy(hkm,C_287,'DisplayName','287 sim') %[output:7c3dffe5]
hold on %[output:7c3dffe5]
semilogy(hkm,C_299,'DisplayName','299 sim') %[output:7c3dffe5]
plot(hkm,pc_287,'DisplayName','287 real') %[output:7c3dffe5]
plot(hkm,pc_299,'DisplayName','299 real') %[output:7c3dffe5]

hold off %[output:7c3dffe5]
legend %[output:7c3dffe5]
grid on %[output:7c3dffe5]
xlim(x_lim) %[output:7c3dffe5]
ylim([1e-1 1e6]) %[output:7c3dffe5]
figure; %[output:7b9d9a05]
semilogy(hkm,C_287,'DisplayName','287 sim') %[output:7b9d9a05]
hold on %[output:7b9d9a05]
plot(hkm,pc_287,'DisplayName','287 real') %[output:7b9d9a05]
hold off %[output:7b9d9a05]
legend %[output:7b9d9a05]
grid on %[output:7b9d9a05]
xlim(x_lim) %[output:7b9d9a05]
ylim([1e-2 1e6]) %[output:7b9d9a05]
figure; %[output:25f65138]
semilogy(hkm,C_299,'DisplayName','299 sim') %[output:25f65138]
hold on %[output:25f65138]
plot(hkm,pc_299,'DisplayName','299 real') %[output:25f65138]
hold off %[output:25f65138]
legend %[output:25f65138]
grid on %[output:25f65138]
xlim(x_lim) %[output:25f65138]
ylim([1e-1 1e6]) %[output:25f65138]
%%
figure; %[output:189d34d4]
plot(hkm,C_287./movmean(pc_287,100)) %[output:189d34d4]
xlim(x_lim) %[output:189d34d4]
ylim([0 1.5]) %[output:189d34d4]
figure; %[output:35bb32a8]
plot(hkm,C_299./movmean(pc_299,100)) %[output:35bb32a8]
xlim(x_lim) %[output:35bb32a8]
ylim([0 1.5]) %[output:35bb32a8]

